    kafkaDesign: kafkaGuide.sources.design, kafkaConsumer: kafkaGuide.sources.consumerApi,
    outbox: { title: 'AWS · Transactional Outbox', url: 'https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html' },
    cdc: kafkaGuide.sources.outbox,
    inbox: { title: 'Chris Richardson · Idempotent Consumer', url: 'https://microservices.io/patterns/communication-style/idempotent-consumer.html' },
    idempotent: { title: 'AWS Builders Library · Idempotent APIs', url: 'https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/' },
    retry: { title: 'Microsoft · Retry pattern', url: 'https://learn.microsoft.com/en-us/azure/architecture/patterns/retry' },
    breaker: { title: 'Microsoft · Circuit Breaker', url: 'https://learn.microsoft.com/en-us/azure/architecture/patterns/circuit-breaker' },
    kafkaRetry: { title: 'Spring Kafka · Retry topic pattern', url: 'https://docs.spring.io/spring-kafka/reference/retrytopic/how-the-pattern-works.html' },
    saga: { title: 'AWS · Saga orchestration', url: 'https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/saga-orchestration.html' },
